import itertools

def is_king_independent(set_of_points):
    for p1, p2 in itertools.combinations(set_of_points, 2):
        if max(abs(p1[0] - p2[0]), abs(p1[1] - p2[1])) <= 1:
            return False
    return True

def solve():
    grid_size = 3
    grid = [(x, y) for x in range(grid_size) for y in range(grid_size)]

    # Find all independent sets of size >= 2
    independent_sets = []
    for r in range(2, len(grid) + 1):
        for subset in itertools.combinations(grid, r):
            if is_king_independent(subset):
                independent_sets.append(set(subset))

    # For each v, check if v must be in X
    # v must be in X if there exists S in independent_sets such that S U {v} is an independent set
    # AND S \cap {v} is empty.
    # Wait, it's simpler: v must be in X if there exist S1, S2 in independent_sets such that S1 \Delta S2 = {v}
    # No, that's not quite right. S1 \Delta S2 could be {v_1, v_2, ...}
    # But if S1 \Delta S2 is any non-empty set D, then D must hit X.
    # If D = {v}, then v must be in X.
    # So if there exist S1, S2 in independent_sets such that S1 \Delta S2 = {v}, then v must be in X.

    must_be_in_X = set()
    for v in grid:
        # Check if there exists S1, S2 in independent_sets such that S1 \Delta S2 = {v}
        # This is equivalent to: there exists S in independent_sets such that S \cup {v} is an independent set
        # and v is not in S.
        for S in independent_sets:
            if v not in S:
                S_new = S | {v}
                if is_king_independent(list(S_new)):
                    must_be_in_X.add(v)
                    break

    print(f"Grid {grid_size}x{grid_size}, Must be in X: {len(must_be_in_X)}/{len(grid)}")
    # Let's also check the other condition: 
    # v is not in X is okay if every S \in independent_sets hits N[v].
    # This means the maximum independent set in G \ N[v] has size < 2.

    # Let's re-verify the "must be in X" condition more carefully.
    # We need to find a minimum X such that for all S1, S2 in I, (S1 \Delta S2) \cap X is not empty.
    # This is the Hitting Set problem on the family of sets {S1 \Delta S2 \mid S1, S2 \in I, S1 \ne S2}.
    # Let F = {S1 \Delta S2 \mid S1, S2 \in I, S1 \ne S2}. We want min |X| such that X hits every set in F.

    diffs = set()
    for i in range(len(independent_sets)):
        for j in range(i + 1, len(independent_sets)):
            s1 = independent_sets[i]
            s2 = independent_sets[j]
            diff = s1 ^ s2
            diffs.add(frozenset(diff))

    # Now we need the minimum hitting set for diffs.
    # This is a classic NP-hard problem, but for small grids we can solve it.
    # Since we want to see if |X| = |V|, let's see if any diff is a singleton {v}.
    # If any diff is a singleton {v}, then v must be in X.

    singletons = [d for d in diffs if len(d) == 1]
    print(f"Singletons: {len(singletons)} out of {len(diffs)} diffs")

