            s1 = independent_sets[i]
            s2 = independent_sets[j]
            diff = s1 ^ s2
            diffs.add(frozenset(diff))

    singletons = [d for d in diffs if len(d) == 1]
    print(f"Grid {grid_size}x{grid_size}, Singletons: {len(singletons)} out of {len(diffs)} diffs")

    # Let's see if there are any non-singletons that are not hit by the singletons.
    # If a diff D has no singletons in it, it might still be hit by one of the singletons.
    # But if a diff D is {v1, v2}, we need to pick either v1 or v2.
    # If every diff D is hit by the set of singletons, then the singletons are a sufficient X.

